return items.map((item, index) => {
  const response = item.json;
  const data = response.data ?? {};
  const info = data.json_result?.request_info ?? {};
  const failed = response.success === false || data.status === 'failure' || info.success === false;
  const pending = !failed && data.status === 'pending';
  return {
    json: {
      query_id: data.id ?? null,
      status: failed ? 'failure' : pending ? 'pending' : data.status ?? 'unknown',
      ready: !failed && !pending && data.status === 'success',
      parsed_result: !failed && !pending ? data.json_result?.result ?? null : null,
      error_details: failed ? info.error_details ?? response.error ?? response.message ?? [] : [],
    },
    pairedItem: { item: index },
  };
});
